gsap.registerPlugin(ScrollTrigger);
let reduced=matchMedia('(prefers-reduced-motion: reduce)').matches,smoothing=false,lenis,context;
const chapterLabels=['Find the form.','Give it depth.','Make it feel.'],chapterCopies=['A simple shape. A clear beginning.','A different angle changes the story.','A little movement brings it together.'];
function setup(){context?.revert();document.body.classList.toggle('reduced',reduced);document.querySelector('#pause').setAttribute('aria-pressed',reduced);context=gsap.matchMedia();context.add({desktop:'(min-width: 801px)',mobile:'(max-width: 800px)'},({conditions})=>{if(reduced)return;gsap.to('.page-progress',{scaleX:1,ease:'none',scrollTrigger:{trigger:document.body,start:'top top',end:'bottom bottom',scrub:true}});if(conditions.desktop){gsap.timeline({scrollTrigger:{trigger:'.story-scene',start:'top 90px',end:'+=1400',pin:true,scrub:1,onUpdate:self=>{const index=Math.min(2,Math.floor(self.progress*3));document.querySelector('#chapter-label').textContent='CHAPTER 0'+(index+1);document.querySelector('#chapter-title').textContent=chapterLabels[index];document.querySelector('#chapter-copy').textContent=chapterCopies[index];}}}).to('.scene-object',{rotation:70,scale:1.35,ease:'none'}).to('.scene-object i',{borderRadius:'20%',rotation:25,ease:'none'},0).to('.scene-progress span',{width:'100%',ease:'none'},0);
const track=document.querySelector('.horizontal-track');gsap.to(track,{x:()=>-(track.scrollWidth-innerWidth),ease:'none',scrollTrigger:{trigger:'.horizontal-window',start:'top 90px',end:()=>'+='+(track.scrollWidth-innerWidth),pin:true,scrub:1,invalidateOnRefresh:true}});document.querySelectorAll('.story-cards article').forEach((card,i,array)=>{if(i===array.length-1)return;gsap.to(card,{scale:.9,opacity:.65,ease:'none',scrollTrigger:{trigger:array[i+1],start:'top 85%',end:'top 150px',scrub:true}});});}
gsap.from('.reveal-title>span',{y:55,opacity:0,duration:1.2,stagger:.13,ease:'power3.out',scrollTrigger:{trigger:'.reveal-title',start:'top 85%',once:true}});});ScrollTrigger.refresh();}
function destroyLenis(){lenis?.destroy();lenis=undefined;smoothing=false;document.querySelector('#smooth').setAttribute('aria-pressed',false);document.querySelector('#smooth').textContent='Enable Lenis';}
document.querySelector('#smooth').onclick=()=>{if(smoothing){destroyLenis();return;}if(reduced)return;lenis=new Lenis({autoRaf:true,anchors:true,duration:1.1});lenis.on('scroll',ScrollTrigger.update);smoothing=true;document.querySelector('#smooth').setAttribute('aria-pressed',true);document.querySelector('#smooth').textContent='Native scroll';};
document.querySelector('#pause').onclick=()=>{reduced=!reduced;if(reduced)destroyLenis();document.querySelector('#smooth').disabled=reduced;setup();};
matchMedia('(prefers-reduced-motion: reduce)').addEventListener('change',e=>{reduced=e.matches;if(reduced)destroyLenis();document.querySelector('#smooth').disabled=reduced;setup();});document.querySelector('#smooth').disabled=reduced;setup();
window.addEventListener('pagehide',()=>{context?.revert();destroyLenis();});
